# frozen_string_literal: true

module Liquid
  module Specialized
    # Copies mutable plain values (Arrays/Hashes/Strings) per render so that
    # assigning a baked value cannot leak mutations across renders.
    def self.dup_plain(value)
      case value
      when Array
        value.map { |v| dup_plain(v) }
      when Hash
        value.each_with_object({}) { |(k, v), h| h[k] = dup_plain(v) }
      when String
        +value.dup
      else
        value
      end
    end
    # Base class for nodes generated by the specialization pass.
    # Fused nodes carry the render-score weight of everything they folded so
    # that observable resource limits cannot be bypassed.
    class Node
      attr_reader :line_number, :render_score_weight

      def initialize(line_number:, render_score_weight: 1)
        @line_number = line_number
        @render_score_weight = render_score_weight
      end

      def blank?
        false
      end

      def render(context)
        render_to_output_buffer(context, +'')
      end
    end

    # Folds a run of fully known output (raw text and completely evaluated
    # {{ variables }} / {% echo %} tags) plus surviving {{ variables }} into
    # a single node.
    #
    # Each "chunk" is one of:
    #   [:text, string]   - raw template text, emitted verbatim
    #   [:vtext, string]  - text produced by a folded {{ variable }}; the
    #                       global filter (if any) is applied at render time
    #   [:var, variable]  - a surviving Liquid::Variable evaluated per render
    class FusedOutput < Node
      attr_reader :chunks

      def initialize(chunks, line_number:, render_score_weight:, global_filter: nil)
        super(line_number: line_number, render_score_weight: render_score_weight)
        @chunks = chunks
        @global_filter = global_filter
      end

      def render_to_output_buffer(context, output)
        @chunks.each do |kind, payload|
          case kind
          when :text
            output << payload
          when :vtext
            output << (@global_filter ? @global_filter.call(payload) : payload)
          else
            # A surviving variable is an original node: rescue its errors
            # exactly like Liquid::BlockBody.render_node so that following
            # chunks still render.
            begin
              payload.render_to_output_buffer(context, output)
            rescue ::StandardError => exc
              Liquid::BlockBody.rescue_render_node(context, output, payload.line_number, exc, false)
            end
          end
          context.resource_limits.increment_write_score(output)
        end
        output
      end
    end

    # A surviving output/control node that could not be folded but must keep
    # its original position and rendering behavior.
    class Passthrough < Node
      attr_reader :node

      def initialize(node, render_score_weight: 1, write_score_count: 1)
        super(line_number: node.line_number, render_score_weight: render_score_weight)
        @write_score_count = write_score_count
        @node = node
      end

      def blank?
        @node.blank?
      end

      def render_to_output_buffer(context, output)
        @node.render_to_output_buffer(context, output)
        @write_score_count.times { context.resource_limits.increment_write_score(output) }
        output
      end
    end

    # Folded {% assign %} whose right hand side is fully known at specialize
    # time. The assignment still happens on every render (so effects on later
    # expressions and assign-score accounting are preserved), but no filters
    # or lookups are executed anymore. The global filter (if any) is applied
    # at render time, as in Liquid::Variable#render.
    class FusedAssign < Node
      def initialize(to, value, assign_score, line_number:, global_filter: nil)
        super(line_number: line_number, render_score_weight: 1)
        @to = to
        @value = value
        @assign_score = assign_score
        @global_filter = global_filter
      end

      def blank?
        true
      end

      def render_to_output_buffer(context, output)
        value = @global_filter ? @global_filter.call(@value) : @value
        # Liquid::Assign#render_to_output_buffer stores the object directly;
        # copy the frozen baked value so per-render mutations cannot leak
        # across renders of the specialized template.
        context.scopes.last[@to] = Specialized.dup_plain(value)
        context.resource_limits.increment_assign_score(@assign_score)
        output
      end
    end

    # Folded {% capture %} whose entire body is fully known at specialize
    # time. The captured string is computed once and assigned per render.
    class FusedCapture < Node
      def initialize(to, value, line_number:)
        super(line_number: line_number, render_score_weight: 1)
        @to = to
        @value = value
      end

      def blank?
        true
      end

      def render_to_output_buffer(context, output)
        context.resource_limits.with_capture do
          # Capture renders into a throwaway buffer; nothing reaches the
          # enclosing output, exactly like Liquid::Capture. The captured
          # bytes are charged to the assign score via with_capture's
          # incremental write accounting.
          captured = +''
          context.resource_limits.increment_write_score(captured)
          captured << @value
          context.resource_limits.increment_write_score(captured)
          context.scopes.last[@to] = @value
        end
        output
      end
    end
  end
end
